// bruteSat evaluates the formula + assumptions over all 2^n assignments.
func bruteSat(n int, clauses [][]int, assumptions []int) bool {
	for mask := 0; mask < (1 << n); mask++ {
		ok := true
		for _, a := range assumptions {
			v := a
			want := true
			if v < 0 {
				v = -v
				want = false
			}
			got := (mask>>(v-1))&1 == 1
			if got != want {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		for _, c := range clauses {
			sat := false
			for _, l := range c {
				v := l
				want := true
				if v < 0 {
					v = -v
					want = false
				}
				got := (mask>>(v-1))&1 == 1
				if got == want {
					sat = true
					break
				}
			}
			if !sat {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
	}
	return false
}

