			want := bruteSat(n, acts, asm)
			if got != want {
				t.Fatalf("chaos iter %d step %d: solve=%v want=%v active=%v asm=%v",
					iter, step, got, want, acts, asm)
			}
			if !got {
				baseUnsat := !bruteSat(n, acts, nil)
				if baseUnsat {
					continue
				}
				core := s.MinimalCore(asmLits...)
				if core == nil {
					t.Fatalf("chaos iter %d step %d: nil core", iter, step)
				}
				if bruteSat(n, acts, toDimacs(core)) {
					t.Fatalf("chaos iter %d step %d: core %v satisfiable under active=%v",
						iter, step, core, acts)
				}
				for i := range core {
					sub := append(append([]Lit{}, core[:i]...), core[i+1:]...)
					if !bruteSat(n, acts, toDimacs(sub)) {
						t.Fatalf("chaos iter %d step %d: core %v not minimal", iter, step, core)
					}
				}
			}
		}
	}
}

// TestMinimumCoreCardinality checks that the exact search finds the true
// minimum even when a minimal (irredundant) core would be larger.
func TestMinimumCoreCardinality(t *testing.T) {
	// Two disjoint 2-cores; any answer must have size 2.
	s := New()
	s.AddClause(-1, -2)
	s.AddClause(-3, -4)
	asm := []Lit{FromDimacs(1), FromDimacs(2), FromDimacs(3), FromDimacs(4)}
	if got := s.MinimumCore(0, asm...); len(got) != 2 {
		t.Fatalf("disjoint cores: got size %d (%v), want 2", len(got), got)
	}
	// A 1-core and a 3-core; the answer must be the singleton.
	s2 := New()
	s2.AddClause(-1)
	s2.AddClause(-2, -3, -4)
	if got := s2.MinimumCore(0, asm...); len(got) != 1 {
		t.Fatalf("mixed cores: got size %d (%v), want 1", len(got), got)
	}
}
